#include <omp.h>
#include <vector>
#include <array>
#include <cstddef>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    #pragma omp parallel
    {
        std::array<size_t, 10> local_bins{};
        local_bins.fill(0);

        #pragma omp for nowait
        for (std::size_t i = 0; i < x.size(); ++i) {
            int bin = static_cast<int>(x[i] / 10.0);
            if (bin < 0) {
                bin = 0;
            } else if (bin > 9) {
                bin = 9; // places 100 into the last bin
            }
            ++local_bins[static_cast<std::size_t>(bin)];
        }

        for (std::size_t b = 0; b < 10; ++b) {
            #pragma omp atomic
            bins[b] += local_bins[b];
        }
    }
}
